This Terraform configuration creates an AWS S3 bucket for storing AWS CodeBuild build artifacts and defines an AWS CodeBuild project configured to output artifacts to that bucket. It also creates the required IAM service role and permissions allowing CodeBuild to write artifacts to S3 and logs to CloudWatch.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "codebuild_output" {
  bucket        = "students-codebuild-output-${random_id.suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "codebuild_output" {
  bucket = aws_s3_bucket.codebuild_output.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

